return {["fb25_01"]={["down"]=[[fb25_02]],["dsc"]=[[一条青石铺就的驿道向北延伸，道旁种满了树木。往南就是长安城了。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb25_01]],["item1"]=[[fb25item6]],["name"]=[[官道]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb25_02"]={["down"]=[[fb25_04]],["dsc"]=[[这里便是安远门。长安为多朝古都，果然不同凡响，城墙以石灰、糯米和土夯成，固若金汤。一条官道自北门向北延伸，官兵们警惕地注视着过往行人。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb25_02]],["item1"]=[[fb25item5]],["item2"]=[[fb25fyb]],["item3"]=[[wldhpd]],["name"]=[[安远门]],["permission"]=1,["role1"]=[[fb25r02_100]],["role2"]=[[fb25r02_101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_01]]},["fb25_03"]={["dsc"]=[[这里原是西北和康藏一带喇嘛进京时的住宿地，后来建成格鲁派（黄教）寺庙。由于这里进出都是喇嘛，因此大家都叫这里喇嘛庙。真名广仁寺反而没多少人知道。]],["id"]=[[fb25_03]],["item1"]=[[fb25item107]],["name"]=[[喇嘛庙]],["permission"]=2,["right"]=[[fb25_04]],["role1"]=[[fb25r03_100]],["role2"]=[[fb25r03_101]],["role3"]=[[2019qxcdg1a]],["role4"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]]},["fb25_04"]={["down"]=[[fb25_08]],["dsc"]=[[你正走在长安北大街上。东边是个酒楼，往北就是城门了。西面一群喇嘛进进出出，原来是个喇嘛庙。里面不知道供的是什么佛爷。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb25_04]],["item1"]=[[fb25item111]],["item2"]=[[fubentiaozhuan1]],["left"]=[[fb25_03]],["name"]=[[北大街]],["permission"]=1,["right"]=[[fb25_05]],["rightUp"]=[[fb25_220]],["role1"]=[[zqtejiang]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_02]]},["fb25_05"]={["dsc"]=[[这里就是天下闻名的谪仙楼，就是李太白醉中做神仙的地方。世人皆知，天下美酒，北有汾酒，南有绍酒。最好的汾酒不在山西，而就在这里。你闻着满楼酒香，原来都是从地窖中飘出来的。]],["id"]=[[fb25_05]],["item1"]=[[fb25item4]],["item2"]=[[fb25r05_5]],["left"]=[[fb25_04]],["name"]=[[谪仙楼]],["permission"]=1,["rightDown"]=[[fb25_06]],["role1"]=[[fb25r05_1]],["role2"]=[[fb25r05_2]],["role3"]=[[fb25r05_3]],["role4"]=[[fb25r05_4]],["stepMusic"]=[[jiaobu]]},["fb25_06"]={["dsc"]=[[地窖里漫着酒池，二百多个酒坛子都成了破瓷块，原来是有个贼徒要巴结华山上的高徒，便从这抱走了两坛酒送上华山。临走时将酒都砸了个七七八八，仅剩下这么几坛。]],["id"]=[[fb25_06]],["item1"]=[[fb25item2]],["item2"]=[[fb25item2]],["leftUp"]=[[fb25_05]],["name"]=[[地窖]],["permission"]=2,["role1"]=[[fb25r06_2]],["role2"]=[[fb25r06_3]],["role3"]=[[fb25r06_100]],["stepMusic"]=[[jiaobu]]},["fb25_07"]={["dsc"]=[[这是一家老字号的钱庄，相老板是山西人，这家钱庄从他的爷爷的爷爷的爷爷的爷爷那辈开始办起，一直传到他手里，声誉非常好，在全国各地都有分店。]],["id"]=[[fb25_07]],["name"]=[[钱庄]],["permission"]=2,["right"]=[[fb25_08]],["role1"]=[[fb25r07_1]],["role2"]=[[fb25r07_100]],["stepMusic"]=[[jiaobu]]},["fb25_08"]={["down"]=[[fb25_17]],["dsc"]=[[你正走在长安北大街上。西边是一家钱庄，可以听到叮叮当当的金银声音。东边个兵营，长安守军驻扎在内，不时传来操练之声。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb25_08]],["left"]=[[fb25_07]],["name"]=[[北大街]],["permission"]=1,["right"]=[[fb25_09]],["role1"]=[[liangongnpc1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_04]]},["fb25_09"]={["dsc"]=[[这里是长安守军驻扎地，一对官兵正在操练，两旁放置着一些剑，长枪，刀之类的武器。你最好赶紧走开，不然被随便安个罪名关进大牢可不是好玩的。]],["id"]=[[fb25_09]],["item1"]=[[fb25r09_100]],["item2"]=[[fb25r09_101]],["left"]=[[fb25_08]],["name"]=[[兵营]],["permission"]=2,["role1"]=[[fb25r09_1]],["role2"]=[[fb25r09_2]],["role3"]=[[fb25r09_3]],["role4"]=[[fb25r09_4]],["stepMusic"]=[[jiaobu]]},["fb25_10"]={["dsc"]=[[钟楼建于明洪武一十三年。青条石为方基，巨木为塔楼。楼内悬挂巨钟一口，用以报时，钟楼因此得名。]],["id"]=[[fb25_10]],["name"]=[[钟楼]],["permission"]=2,["rightDown"]=[[fb25_17]],["role1"]=[[fb25r10_1]],["role2"]=[[fb25r10_2]],["role3"]=[[fb25r10_3]],["stepMusic"]=[[jiaobu]]},["fb25_100"]={["down"]=[[fb25_99]],["dsc"]=[[只见迷迷茫茫全是参天大树，遮天闭日，四周光线很暗，分不清东南西北，任是谁进来都别想再出去了。]],["fightBackground"]=[[森林内]],["id"]=[[fb25_100]],["item1"]=[[assitem93]],["item2"]=[[assitem94]],["item3"]=[[assitem95]],["item4"]=[[assitem96]],["left"]=[[fb25_99]],["name"]=[[密林]],["permission"]=2,["right"]=[[fb25_99]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_101]]},["fb25_101"]={["down"]=[[fb25_100]],["dsc"]=[[只见迷迷茫茫全是参天大树，遮天闭日，四周光线很暗，分不清东南西北，任是谁进来都别想再出去了。]],["fightBackground"]=[[森林内]],["id"]=[[fb25_101]],["item1"]=[[assitem93]],["item2"]=[[assitem94]],["item3"]=[[assitem95]],["item4"]=[[assitem96]],["left"]=[[fb25_99]],["name"]=[[密林]],["permission"]=2,["right"]=[[fb25_102]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_99]]},["fb25_102"]={["down"]=[[fb25_99]],["dsc"]=[[只见迷迷茫茫全是参天大树，遮天闭日，四周光线很暗，分不清东南西北，任是谁进来都别想再出去了。]],["fightBackground"]=[[森林内]],["id"]=[[fb25_102]],["item1"]=[[as