[山路]],["permission"]=2,["right"]=[[fb25_209]],["stepMusic"]=[[jiaobu]]},["fb25_209"]={["dsc"]=[[这是一条上山的小路，十分陡峭崎岖，即使是练武之人也极难前行，周围满是荒凉，路旁只有稀疏的几颗小树。]],["id"]=[[fb25_209]],["left"]=[[fb25_208]],["name"]=[[山路]],["permission"]=2,["right"]=[[fb25_210]],["stepMusic"]=[[jiaobu]]},["fb25_21"]={["dsc"]=[[这里就是古函古关。它东起崤山，西接潼津，关设谷中。当年强秦一隅之地，制关东六国而不敢稍动，最后横扫天下，就是因为它据此，进可攻，退可守，乃天下形胜之处。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb25_21]],["left"]=[[fb25_20]],["name"]=[[关中官道]],["permission"]=2,["role1"]=[[fb25r21_1]],["stepMusic"]=[[jiaobu]]},["fb25_210"]={["dsc"]=[[这是一条下山的小路，周围满是荒凉，路旁只有稀疏的几颗小树。]],["id"]=[[fb25_210]],["left"]=[[fb25_209]],["name"]=[[山路]],["permission"]=2,["right"]=[[fb25_211]],["role1"]=[[assr210_1]],["role2"]=[[assr210_2]],["stepMusic"]=[[jiaobu]]},["fb25_211"]={["dsc"]=[[这是一条下山的小路，周围满是荒凉，路旁只有稀疏的几颗小树。]],["id"]=[[fb25_211]],["left"]=[[fb25_210]],["name"]=[[山路]],["permission"]=2,["right"]=[[fb25_212]],["stepMusic"]=[[jiaobu]]},["fb25_212"]={["down"]=[[fb25_213]],["dsc"]=[[这是一条下山的小路，周围满是荒凉，路旁只有稀疏的几颗小树。]],["id"]=[[fb25_212]],["left"]=[[fb25_211]],["name"]=[[山路]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb25_213"]={["down"]=[[fb25_214]],["dsc"]=[[你走在一条尘土飞扬的黄土路上，四周景色凄惨，看来是到了人迹罕至的荒凉之地。]],["id"]=[[fb25_213]],["name"]=[[黄土路]],["permission"]=2,["role1"]=[[assitem177]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_212]]},["fb25_214"]={["down"]=[[fb25_215]],["dsc"]=[[你走在一条尘土飞扬的黄土路上，四周景色凄惨，看来是到了人迹罕至的荒凉之地。]],["id"]=[[fb25_214]],["name"]=[[黄土路]],["permission"]=2,["role1"]=[[assitem177]],["role2"]=[[assitem184]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_213]]},["fb25_215"]={["down"]=[[fb25_216]],["dsc"]=[[你走在一条尘土飞扬的黄土路上，四周景色凄惨，看来是到了人迹罕至的荒凉之地。]],["id"]=[[fb25_215]],["name"]=[[黄土路]],["permission"]=2,["role1"]=[[assitem177]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_214]]},["fb25_216"]={["down"]=[[fb25_217]],["dsc"]=[[这里是一片青草地，青草长势茂盛，便是一个成人躺在地上都不一定被发现。]],["id"]=[[fb25_216]],["name"]=[[草地]],["permission"]=2,["role1"]=[[assitem177]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_215]]},["fb25_217"]={["down"]=[[fb25_218]],["dsc"]=[[这里是一片青草地，青草长势茂盛，便是一个成人躺在地上都不一定被发现。]],["id"]=[[fb25_217]],["name"]=[[草地]],["permission"]=2,["role1"]=[[assitem177]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_216]]},["fb25_218"]={["down"]=[[fb25_107]],["dsc"]=[[这里是一片青草地，青草长势茂盛，便是一个成人躺在地上都不一定被发现。]],["id"]=[[fb25_218]],["name"]=[[草地]],["permission"]=2,["role1"]=[[assr218_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_217]]},["fb25_219"]={["dsc"]=[[你刚走进这校军场，便看到一对对整齐的官兵在武将的指挥下操练，有的士兵正在墙角下休息，看到你进来，他们全都瞪大眼睛盯着你。]],["id"]=[[fb25_219]],["name"]=[[校军场]],["permission"]=2,["role1"]=[[zjsrnpc]],["role2"]=[[ybrr219_02]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_13]]},["fb25_22"]={["dsc"]=[[这里便是阿房宫，四下便是黄土、乱石，哪里看得出有什么宫殿？不远处立着块石碑。]],["id"]=[[fb25_22]],["item1"]=[[fb25item108]],["name"]=[[阿房宫]],["permission"]=2,["role1"]=[[liangongnpc2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_15]]},["fb25_220"]={["id"]=[[fb25_220]],["name"]=[[长安北大街]],["permission"]=2,["role1"]=[[fubentiaozhuan5]],["stepMusic"]=[[jiaobu]]},["fb25_221"]={["id"]=[[fb25_221]],["name"]=[[长安南大街]],["permission"]=2,["role1"]=[[fubentiaozhuan6]],["stepMusic"]=[[jiaobu]]},["fb25_222"]={["id"]=[[fb25_222]],["name"]=[[长安西大街]],["permission"]=2,["role1"]=[[fubentiaozhuan7]],["stepMusic"]=[[jiaobu]]},["fb25_223"]={["id"]=[[fb25_223]],["name"]=[[长安东大街]],["permission"]=2,["role1"]=[[fubentiaozhuan8]],["stepMusic"]=[[jiaobu]]},["fb25_224"]={["down"]=[[fb25_20]],["dsc"]=[[这是长安城新开的一家花店，店主是一位虚渺宫弟子。]],["id"]=[[fb25_224]],["name"]=[[百合居]],["permission"]=2,["role1"]=[[tstsnpc1a]],["stepMusic"]=[[jiaobu]]},["fb25_23"]={["dsc"]=[[关中书院是甘陕地区最高学府，建于明万历年间。这里的老师学识渊博，或许可以在这学习读书识字。]],["id"]=[[fb25_23]],["item1"]=[[yuanzhang1]],["name"]=[[关中书院]],["permission"]=2,["role1"]=[[fb25r23_1]],["role2"]=[[fb25r23_2]],["role3"]=[[fb25r23_3]],["role4"]=[[fb25r23_100]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_18]]},["fb25_24"]={["dsc"]=[[这是一家专卖旅游纪念品的小铺子。到了长安不买点纪念品，说不过去吧......一个大嫂正站在铺前向游客招揽生意。]],["id"]=[[fb25_24]],["name"]=[[小铺子]],["permission"]=2,["role1"]=[[fb25r24_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_19]]},["fb25_25"]={["down"]=[[fb25_29]],["dsc"]=[[这里便是天下闻名的长安碑林。相传建于北宋元佑年间。碑林里碑石墓志林立，自汉至清，荟萃各代名家手笔。真草隶篆，琳琅满目。]],["id"]=[[fb25_25]],["item1"]=[[fb25item114]],["name"]=[[碑林]],["permission"]=2,["right"]=[[fb25_26]],["role1"]=[[fb25r25_1]],["stepMusic"]=[[jiaobu]]},["fb25_26"]={["down"]=[[fb25_30]],["dsc"]=[[你走在一条幽静的青石小巷中，巷两边种着一行枣树。不料繁华的长安城内也有如此悠然去处。一阵枣香、一丝茶意、一声丝竹如远处高楼的歌声，隐隐飘来。]],["id"]=[[fb25_26]],["item1"]=[[fb25item7]],["item2"]=[[fb25item7]],["item3"]=[[fb25item109]],["left"]=[[fb25_25]],["name"]=[[枣巷]],["permission"]=2,["right"]=[[fb25_27]],["role1"]=[[liangongnpc3]],["stepMusic"]=[[jiaobu]]},["fb25_27"]={["down"]=[[fb25_32]],["dsc"]=[[你正走在长安南大街上，北边是一个热闹的广场，人声鼎沸，东边不时地传来金属撞击声，和西边安静的小巷形成鲜明的对比。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb25_27]],["left"]=[[fb25_26]],["name"]=[[南大街]],["permission"]=2,["right"]=[[fb25_28]],["role1"]=[[fb25r27_1]],["role2"]=[[fb25r27_5]],["role3"]=[[fb25r27_6]],["role4"]=[[dhr27_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_17]]},["fb25_28"]={["dsc"]=[[这里是打铁铺，四周的墙上挂着铁器，大部分都是已经打好的铁锤，长剑，菜刀，匕首等物。中间摆着个旺盛的火炉，一个铁匠正在火炉旁卖力的敲打着。]],["id"]=[[fb25_28]],["item1"]=[[duanzaoronglu1]],["left"]=[[fb25_27]],["name"]=[[打铁铺]],["permission"]=2,["role1"]=[[fb25r28_1]],["role2"]=[[fb25r28_2]],["role3"]=[[fb25r28_3]],["role4"]=[[dhr28_1]],["stepMusic"]=[[jiaobu]]},["fb25_29"]={["dsc"]=[[你一走进来，就闻到一股茶香沁入心脾，精神为之一爽。几张八仙桌一字排开，坐满了客人。一位老者正在堂前弹奏，几个儒生击几而歌。的确是个悠然去处。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb25_29]],["item1"]=[[fb25item100]],["name"]=[[清馨茶馆]],["permission"]=2,["role1"]=[[fb25r29_1]],["role2"]=[[fb25r29_2]],["role3"]=[[fb25r29_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_25]]},["fb25_30"]={["dsc"]=[[东岳就是泰山，历代天子认为山高有灵，因此建庙祭祀。此庙建于北宋政和六年。大殿宏伟壮观，东西殿墙上画着不少楼阁仕女，远非普通宗教题材之壁画可比，颇有元明气韵。]],["id"]=[[fb25_30]],["item1"]=[[fb25item112]],["item2"]=[[fb25item113]],["item3"]=[[lylitem1]],["name"]=[[东岳庙]],["permission"]=2,["role1"]=[[fb25r30_100]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_26]]},["fb25_31"]={["dsc"]=[[这里是长安驿站。由于各个城市进出长安的物资传送都要通过这里，因此驿站里人群进进出出，一片忙碌的景象。站前竖着一溜石桩，绑着一些驿马和大车，几个车夫正在四处招揽生意。]],["id"]=[[fb25_31]],["name"]=[[驿站]],["permission"]=2,["right"]=[[fb25_32]],["role1"]=[[fb25r31_1]],["stepMusic"]=[[jiaobu]]},["fb25_32"]={["down"]=[[fb25_34]],["dsc"]=[[你走在长安大街之上，往西是城中驿站，往东是南北行。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb25_32]],["item1"]=[[fubentiaozhuan2]],["left"]=[[fb25_31]],["leftDown"]=[[fb25_221]],["name"]=[[南大街]],["permission"]=2,["right"]=[[fb25_33]],["role1"]=[[fb25r32_1]],["role2"]=[[fb25r32_2]],["role3"]=[[dhr32_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_27]]},["fb25_33"]={["dsc"]=[[这是一家气派不小的杂货铺，门楼高挂一个牌匾，上书红底金色三个大字----“南北行”。掌柜懒洋洋地坐柜台后，几个伙计忙里忙外。柜台上立着一块招牌。]],["id"]=[[fb25_33]],["left"]=[[fb25_32]],["name"]=[[南北行]],["permission"]=2,["role1"]=[[fb25r33_1]],["role2"]=[[dhr33_1]],["stepMusic"]=[[jiaobu]]},["fb25_34"]={["down"]=[[fb25_36]],["dsc"]=[[这里便是长安南门----永宁门。长安为多朝古都，果然不同凡响，城墙以石灰、糯米和土夯成，固若金汤。出了城门便是官道，几名官兵正在守门。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb25_34]],["name"]=[[永宁门]],["permission"]=2,["rightDown"]=[[fb25_35]],["role1"]=[[fb25r34_1]],["role2"]=[[fb25r34_2]],["role3"]=[[liangongnpc5]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_32]]},["fb25_35"]={["dsc"]=[[这是永宁门上的一个城楼，极目四望，可以看到南边青青的终南山。旁边几个官兵正在休息。不过这里是军事重地，你最好还是赶快离开。]],["id"]=[[fb25_35]],["item1"]=[[fb25item115]],["leftUp"]=[[fb25_34]],["name"]=[[奎星楼]],["permission"]=2,["role1"]=[[fb25r35_1]],["role2"]=[[fb25r35_2]],["role3"]=[[fb25r35_3]],["role4"]=[[fb25r35_4]],["stepMusic"]=[[jiaobu]]},["fb25_36"]={["dsc"]=[[这是一条青石铺就的宽阔笔直的官道，道旁种满了路树，足可容得下十马并驰。往东南通向大雁塔，往西南通向小雁塔。往北则直达长安城。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb25_36]],["item1"]=[[fb25r36_104]],["leftDown"]=[[fb25_37]],["name"]=[[官道]],["permission"]=2,["rightDown"]=[[fb25_38]],["role1"]=[[fb25r36_100]],["role2"]=[[fb25r36_101]],["role3"]=[[fb25r36_102]],["role4"]=[[fb25r36_103]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_34]]},["fb25_37"]={["dsc"]=[[小雁塔建于景龙年间，因比大雁塔小，故称小雁塔。塔高十五级，双塔连理为一塔，形体秀丽美观。]],["id"]=[[fb25_37]],["item1"]=[[fb25item11]],["name"]=[[小雁塔]],["permission"]=2,["rightUp"]=[[fb25_36]],["role1"]=[[fb25r37_1]],["role2"]=[[fb25r37_2]],["role3"]=[[fb25r37_3]],["stepMusic"]=[[jiaobu]]},["fb25_38"]={["down"]=[[fb25_92]],["dsc"]=[[唐永徽三年，圣僧玄奘为保护佛家经书，由唐高宗资助建成此塔。《三藏法师传》记载:摩揭国有一寺，一雁离群落羽，摔死地上，僧以为雁即菩萨，建塔纪念，故名大雁塔。]],["id"]=[[fb25_38]],["item1"]=[[fb25item10]],["item2"]=[[assitem116]],["leftUp"]=[[fb25_36]],["name"]=[[大雁塔]],["permission"]=2,["role1"]=[[fb25r38_100b]],["stepMusic"]=[[jiaobu]]},["fb25_39"]={["dsc"]=[[这是长安城的知府衙门，门前一片肃静，只见上面四个大字:公正廉明。]],["id"]=[[fb25_39]],["item1"]=[[changan003]],["name"]=[[衙门]],["permission"]=2,["role1"]=[[fb25r39_1]],["role2"]=[[ybritem1]],["role3"]=[[ybrr39_02]],["role4"]=[[ybrr39_03]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_16]]},["fb25_40"]={["dsc"]=[[你走在一条尘土飞扬的黄土路上，四周景色凄惨，看来是到了人迹罕至的荒凉之地。]],["fightBackground"]=[[山内]],["id"]=[[fb25_40]],["name"]=[[黄土路]],["permission"]=2,["right"]=[[fb25_41]],["stepMusic"]=[[jiaobu]]},["fb25_41"]={["down"]=[[fb25_48]],["dsc"]=[[你走在一条尘土飞扬的黄土路上，四周景色凄惨，看来是到了人迹罕至的荒凉之地。]],["fightBackground"]=[[山内]],["id"]=[[fb25_41]],["left"]=[[fb25_40]],["name"]=[[黄土路]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb25_42"]={["dsc"]=[[你走在一条尘土飞扬的黄土路上，四周景色凄惨，看来是到了人迹罕至的荒凉之地。]],["fightBackground"]=[[山内]],["id"]=[[fb25_42]],["item1"]=[[assitem29]],["item2"]=[[assitem30]],["item3"]=[[assitem31]],["leftDown"]=[[fb25_48]],["name"]=[[黄土路]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb25_43"]={["dsc"]=[[你走在一条尘土飞扬的黄土路上，四周景色凄惨，看来是到了人迹罕至的荒凉之地。]],["fightBackground"]=[[山内]],["id"]=[[fb25_43]],["name"]=[[黄土路]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb25_105]]},["fb25_44"]={["down"]=[[fb25_51]],["dsc"]=[[你走在一条尘土飞扬的黄土路上，四周景色凄惨，看来是到了人迹罕至的荒凉之地。]],["fightBackground"]=[[山内]],["id"]=[[fb25_44]],["name"]=[[黄土路]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb25_45"]={["dsc"]=[[你走在一条尘土飞扬的黄土路上，四周景色凄惨，看来是到了人迹罕至的荒凉之地。]],["fightBackground"]=[[山内]],["id"]=[[fb25_45]],["item1"]=[[assitem15]],["item2"]=[[assitem28]],["name"]=[[黄土路]],["permission"]=2,["rightDown"]=[[fb25_53]],["stepMusic"]=[[jiaobu]]},["fb25_46"]={["down"]=[[fb25_53]],["dsc"]=[[你走在一条尘土飞扬的黄土路上，四周景色凄惨，看来是到了人迹罕至的荒凉之地。]],["fightBackground"]=[[山内]],["id"]=[[fb25_46]],["item1"]=[[assitem121]],["name"]=[[黄土路]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb25_47"]={["down"]=[[fb25_54]],["dsc"]=[[虽说是小道，其实不过是被行人将地上的杂草踩低形成的罢了。小道周围树影婆娑，鬼影重重，让人不禁心惊肉跳。]],["fightBackground"]=[[森林内]],["id"]=[[fb25_47]],["name"]=[[林中小道]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb25_178]]},["fb25_48"]={["down"]=[[fb25_56]],["dsc"]=[[你走在一条尘土飞扬的黄土路上，四周景色凄惨，看来是到了人迹罕至的荒凉之地。]],["fightBackground"]=[[山内]],["id"]=[[fb25_48]],["item1"]=[[assitem1]],["item2"]=[[assitem173]],["name"]=[[黄土路]],["permission"]=2,["rightUp"]=[[fb25_42]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_41]]},["fb25_49"]={["down"]=[[fb25_58]],["dsc"]=[[虽说是小道，其实不过是被路人将地上的杂草形成的罢了。小道周围树影婆娑，鬼影重重，让人不禁心惊肉跳。]],["fightBackground"]=[[森林内]],["id"]=[[fb25_49]],["item1"]=[[assitem2]],["name"]=[[林中小道]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb25_50"]={["down"]=[[fb25_59]],["dsc"]=[[你走在一条尘土飞扬的黄土路上，四周景色凄惨，看来是到了人迹罕至的荒凉之地。]],["fightBackground"]=[[山内]],["id"]=[[fb25_50]],["item1"]=[[assitem117]],["name"]=[[黄土路]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb25_51"]={["down"]=[[fb25_60]],["dsc"]=[[你走在一条尘土飞扬的黄土路上，四周景色凄惨，看来是到了人迹罕至的荒凉之地。]],["fightBackground"]=[[山内]],["id"]=[[fb25_51]],["name"]=[[黄土路]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb25_44]]},["fb25_52"]={["down"]=[[fb25_61]],["dsc"]=[[你走在一条尘土飞扬的黄土路上，四周景色凄惨，看来是到了人迹罕至的荒凉之地。]],["fightBackground"]=[[山内]],["id"]=[[fb25_52]],["item1"]=[[assitem133]],["name"]=[[黄土路]],["permission"]=2,["right"]=[[fb25_53]],["role1"]=[[assr52_1]],["role2"]=[[assr52_2]],["stepMusic"]=[[jiaobu]]},["fb25_53"]={["dsc"]=[[你走在一条尘土飞扬的黄土路上，四周景色凄惨，看来是到了人迹罕至的荒凉之地。]],["fightBackground"]=[[山内]],["id"]=[[fb25_53]],["item1"]=[[assitem27]],["left"]=[[fb25_52]],["leftUp"]=[[fb25_45]],["name"]=[[黄土路]],["permission"]=2,["role1"]=[[assr53_1]],["role2"]=[[assr53_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb25_46]]},["fb25_54"]={["dsc"]=[[虽说是小道，其实不过是被路人将地上的杂草形成的罢了。小道周围树影婆娑，鬼影重重，让人不禁心惊肉跳。]],["fightBackgroun